from soar.playbooks.template import referenced_paths

problems = []
kinds = node_kinds()
nodes = definition.get("nodes", {})
start = definition.get("start")

if start not in nodes:
    return ["start node %r is not in the graph" % start]

# 1. Every edge points somewhere real.
for node_id, node in sorted(nodes.items()):
    kind = node.get("kind")
    if kind not in kinds:
        problems.append("%s: unknown node kind %r" % (node_id, kind))
        continue
    for field in kinds[kind]["next"]:
        target = node.get(field)
        if target is None:
            continue
        if isinstance(target, dict) and field == "cases":
            targets = list(target.values())
        else:
            targets = target if isinstance(target, list) else [target]
        for one in targets:
            name = one.get("then") if isinstance(one, dict) else one
            if name and name not in nodes:
                problems.append("%s.%s points at missing node %r"
                                % (node_id, field, name))

# 2. Nothing unreachable. An orphan node is either a mistake or a leftover,
#    and both are worth stopping at publish.
def edges_from(node):
    # Every way out of a node, whatever shape the kind writes them in:
    # a plain name, a list of condition clauses, a map of switch cases,
    # and the compensation that runs if a later step fails.
    out = []
    for field in kinds.get(node.get("kind"), {}).get("next", []):
        target = node.get(field)
        if isinstance(target, dict) and field == "cases":
            out.extend(str(v) for v in target.values())
            continue
        for one in (target if isinstance(target, list) else [target]):
            name = one.get("then") if isinstance(one, dict) else one
            if name:
                out.append(name)
    if node.get("compensation"):
        out.append(node["compensation"])
    return out

seen, frontier = set(), [start]
while frontier:
    current = frontier.pop()
    if current in seen or current not in nodes:
        continue
    seen.add(current)
    frontier.extend(edges_from(nodes[current]))
for orphan in sorted(set(nodes) - seen):
    problems.append("%s is unreachable from start" % orphan)

# 3. A branch must be written as branches. "when": "some_node" reads like
#    it works, points at a node that exists, and passes every check above -
#    and then iterates a string at 03:00 rather than deciding anything.
for node_id, node in sorted(nodes.items()):
    if node.get("kind") != "condition":
        continue
    clauses = node.get("when")
    if not isinstance(clauses, list) or not clauses:
        problems.append(
            "%s: a condition needs when=[{\"if\": ..., \"then\": ...}]" % node_id)
        continue
    for clause in clauses:
        if not isinstance(clause, dict) or not clause.get("if"):
            problems.append("%s: every when clause needs an if" % node_id)
        elif not clause.get("then"):
            problems.append(
                "%s: when clause %r names no node to go to"
                % (node_id, clause.get("if")))

# A format node with no template renders an empty string into whatever
# it feeds - an email with no body, an alert with no description.
for node_id, node in sorted(nodes.items()):
    if node.get("kind") != "format":
        continue
    if not (node.get("template") or "").strip():
        problems.append("%s: a format node needs a template" % node_id)
    if node.get("format") not in (None, "html", "text", "markdown"):
        problems.append("%s: format is html, text or markdown" % node_id)

# 4. Every loop is bounded. An unbounded loop in a SOAR is an outage.
for node_id, node in sorted(nodes.items()):
    if kinds.get(node.get("kind"), {}).get("bounded"):
        limit = node.get("max_iterations")
        if not isinstance(limit, int) or limit <= 0 or limit > 10000:
            problems.append(
                "%s: %s needs max_iterations between 1 and 10000"
                % (node_id, node.get("kind"))
            )

# 5. A HIGH-risk approval may not proceed on timeout. Not discouraged: refused.
for node_id, node in sorted(nodes.items()):
    if node.get("kind") != "approval":
        continue
    if node.get("risk_level") == "high" and node.get("on_timeout") == "proceed":
        problems.append(
            "%s: a high-risk approval cannot proceed on timeout" % node_id
        )
    if not node.get("action_key"):
        problems.append("%s: an approval must name the action it gates" % node_id)

# 6. Compensation targets must exist and be declared idempotent.
for node_id, node in sorted(nodes.items()):
    compensation = node.get("compensation")
    if compensation and compensation not in nodes:
        problems.append("%s: compensation %r is not a node" % (node_id, compensation))

# 7. Templates may only read paths the context will actually contain.
known = {"incident", "alert", "inputs", "steps", "vars", "globals", "host",
         "user", "indicator", "integration", "execution"}
declared = {v["name"] for v in definition.get("variables", [])}
# A node that names its output puts that name in scope for every node
# after it, the same as a declared variable.
declared |= {node["output_var"] for node in nodes.values()
             if node.get("output_var")}
# And a loop names the item it is holding, for the length of its body.
declared |= {node["as"] for node in nodes.values() if node.get("as")}
for node_id, node in sorted(nodes.items()):
    for value in (node.get("inputs") or {}).values():
        for path in referenced_paths(value):
            root = path.split(".")[0].split("[")[0]
            if root and root not in known and root not in declared:
                problems.append(
                    "%s: template reads %r, which nothing puts in scope"
                    % (node_id, path)
                )
return problems

def children(pid):
    rows = db.query(
        "SELECT pv.definition FROM playbook p "
        "JOIN playbook_version pv ON pv.id = p.current_version_id "
        "WHERE p.id = %s AND p.org_id = %s", [pid, org_id], org_id,
    )
    if not rows:
        return []
    return [
        node.get("playbook")
        for node in (rows[0]["definition"].get("nodes") or {}).values()
        if node.get("kind") == "sub_playbook" and node.get("playbook")
    ]

direct = [
    node.get("playbook") for node in (definition.get("nodes") or {}).values()
    if node.get("kind") == "sub_playbook" and node.get("playbook")
]

problems = []
for target in direct:
    seen, frontier = set(), [target]
    while frontier:
        current = frontier.pop()
        if current == playbook_id:
            problems.append("sub-playbook cycle through %s" % target)
            break
        if current in seen:
            continue
        seen.add(current)
        frontier.extend(children(current))
return problems
